def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"[0-9]+|[A-Z]+[0-9]+|[A-Z]+|<>|<=|>=|[()+*/,:<>=-]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            part = text[i:i + 9]
            value = value * (10 ** len(part)) + int(part)
        return -value if negative else value

    def parse(formula):
        tokens = token_pattern.findall(formula)
        nodes = []
        operators = []
        expect_operand = True

        def apply_operator():
            op = operators.pop()[1]
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in tokens:
            if token[0].isdigit():
                nodes.append(("number", integer(token)))
                expect_operand = False
            elif token[0].isalpha():
                if token in ("SUM", "MIN", "MAX", "IF"):
                    operators.append(("function", token))
                    expect_operand = True
                else:
                    nodes.append(("reference", token))
                    expect_operand = False
            elif token == "(":
                operators.append(["parenthesis", 0])
                expect_operand = True
            elif token == ",":
                while operators[-1][0] == "operator":
                    apply_operator()
                operators[-1][1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1][0] == "operator":
                    apply_operator()
                argument_count = operators.pop()[1] + 1
                if operators and operators[-1][0] == "function":
                    name = operators.pop()[1]
                    arguments = nodes[-argument_count:]
                    del nodes[-argument_count:]
                    nodes.append(("function", name, arguments))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while (
                    operators
                    and operators[-1][0] == "operator"
                    and (
                        precedence[operators[-1][1]] > precedence[op]
                        or (
                            precedence[operators[-1][1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    apply_operator()
                operators.append(("operator", op))
                expect_operand = True

        while operators:
            apply_operator()
        return nodes[0]

    def function_arguments(arguments):
        for argument in arguments:
            if argument[0] != ":":
                yield argument
                continue

            first = argument[1][1]
            second = argument[2][1]
            left, right = sorted((ord(first[0]), ord(second[0])))
            top, bottom = sorted((int(first[1:]), int(second[1:])))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    values = {}
    active = set()
    parsed = {}

    for root in cells:
        if root in values:
            continue

        tasks = [("cell", root)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    results.append(0)
                elif name in values:
                    results.append(values[name])
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    if content.startswith("="):
                        if name not in parsed:
                            parsed[name] = parse(content[1:])
                        tasks.append(("finish_cell", name))
                        tasks.append(("evaluate", parsed[name]))
                    else:
                        value = integer(content)
                        active.remove(name)
                        values[name] = value
                        results.append(value)

            elif kind == "finish_cell":
                name = task[1]
                active.remove(name)
                values[name] = results[-1]

            elif kind == "evaluate":
                node = task[1]
                op = node[0]

                if op == "number":
                    results.append(node[1])
                elif op == "reference":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))
                elif op == "function":
                    name, arguments = node[1], node[2]
                    if name == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("evaluate", arguments[0]))
                    else:
                        iterator = iter(function_arguments(arguments))
                        tasks.append(("next_argument", name, iterator, None))
                else:
                    tasks.append(("left_operand", op, node[2]))
                    tasks.append(("evaluate", node[1]))

            elif kind == "negate":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "left_operand":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("right_operand", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif kind == "right_operand":
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        value = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            value = -value
                elif op == "=":
                    value = left == right
                elif op == "<>":
                    value = left != right
                elif op == "<":
                    value = left < right
                elif op == "<=":
                    value = left <= right
                elif op == ">":
                    value = left > right
                else:
                    value = left >= right
                results.append(value)

            elif kind == "choose":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("evaluate", task[1] if condition else task[2]))

            elif kind == "next_argument":
                name, iterator, accumulated = task[1], task[2], task[3]
                try:
                    argument = next(iterator)
                except StopIteration:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("combine_argument", name, iterator, accumulated))
                    tasks.append(("evaluate", argument))

            else:
                name, iterator, accumulated = task[1], task[2], task[3]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif name == "SUM":
                        accumulated += value
                    elif name == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("next_argument", name, iterator, accumulated))

    return {name: values[name] for name in cells}
